let courseKind="all",chosenCourse=null,typingSession=null,typingTimer=null;
const COURSE_PROJECTS={redes:{task:'Projete uma rede pequena em um simulador: 2 setores com 20 dispositivos cada, uma rede de visitantes e acesso à internet. Use o bloco privado 192.168.10.0/24, documente sub-redes, gateways, VLANs e testes.',steps:['Divida em /27: cada sub-rede convencional oferece 30 endereços de host. Reserve 192.168.10.0/27, .32/27 e .64/27 para os três grupos.','Use gateways .1, .33 e .65, respectivamente. Associe cada grupo a uma VLAN distinta; o roteamento entre VLANs exige dispositivo de camada 3 e política explícita.','Planeje DHCP sem incluir gateways na faixa dinâmica. Permita internet aos visitantes, bloqueie acesso deles às redes internas e documente DNS e NAT na borda.','No simulador, teste conexão dentro da VLAN, resolução de nomes e os bloqueios. Simule uma falha de gateway e registre hipótese, teste e correção. QoS prioriza tráfego, mas não cria banda.']},hardware:{task:'Produza uma ficha de montagem e um roteiro de manutenção para um computador de estudo. Você pode executar este projeto por planejamento, sem abrir um equipamento real.',steps:['Liste CPU, socket/chipset da placa-mãe, tipo e capacidade de RAM, SSD e interfaces. Confirme compatibilidade nos manuais dos fabricantes.','Dimensione a fonte para o conjunto e registre conectores necessários. Não abra uma fonte de alimentação: ela pode manter tensões perigosas mesmo desligada.','Antes de manusear peças: desligue, retire da tomada e siga proteção contra descarga eletrostática indicada pelo fabricante. Não force encaixes. Instalação real requer supervisão se você não tiver experiência.','Registre teste de POST, reconhecimento da RAM/SSD, temperatura e drivers. Antes de reinstalar o sistema, confirme backup recuperável e autorização.','Faça uma ordem de serviço com sintoma, hipótese, teste, solução e verificação final. Não apague dados para experimentar.']},basica:{task:'Organize uma pasta de estudos e crie um pequeno conjunto de documentos para uma semana de preparação.',steps:['Crie pastas Materiais, Exercícios e Revisões. Salve um documento com título, dois parágrafos e uma lista; exporte uma cópia em PDF.','Monte uma planilha com dias, tempo planejado e tempo realizado. Some os minutos e calcule a diferença; confira o resultado manualmente.','Crie três slides com objetivo, conteúdo aprendido e dúvidas. Faça uma cópia de segurança e teste abrir um dos arquivos copiados.','Prepare um e-mail de teste para você mesmo: assunto claro, texto curto e anexo correto. Revise destinatário e arquivo antes de enviar; nunca compartilhe senhas.']},digitacao:{task:'Complete três treinos de 60 segundos em dias diferentes e compare os resultados, com prioridade para a precisão.',steps:['Mantenha a mesma aula e duração para comparar. Anote os grupos de letras que causaram erros.','Repita lentamente os grupos difíceis antes da nova tentativa. Faça pausas e mantenha a postura confortável.','Avalie a evolução pela combinação de precisão e PPM. O histórico guarda as 30 tentativas mais recentes entre todas as aulas.']}};
const courseLessons=STUDY_COURSES.flatMap(c=>c.lessons.map(l=>({...l,courseId:c.id,category:c.title})));
for(const l of courseLessons)VIDEO_CATALOG[l.id]=l.language?languageVideoList(l):l.source?VIDEO_CATALOG[l.source]:[{id:'G7osIEUSmdo',title:'Curso completo de digitação — Aula 1: posição das mãos',by:'Informática para Concursos · introdução; pratique o tema da aula no treinador abaixo',verifiedAt:'2026-11-11'}];
function courseProgress(){state.courses??={};state.courses.done??={};state.courses.notes??={};state.courses.typing??=[];return state.courses}
function coursesHTML(){const p=courseProgress(),c=STUDY_COURSES.find(c=>c.id===chosenCourse);return `<p class="muted">Cursos de informática e idiomas com explicações, atividades e progresso salvo na sua conta. Nos idiomas: 24 aulas, do básico ao avançado, com provas por etapa e avaliação final.</p>${c?`<button id="all-courses">← Todos os cursos</button><section class="course-hero"><span class="eyebrow">SEU CURSO · ${c.lessons.length} AULAS</span><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><p>${c.lessons.filter(l=>p.done[l.id]).length}/${c.lessons.length} aulas concluídas</p><button class="study" data-course-lesson="${(c.lessons.find(l=>!p.done[l.id])||c.lessons[0]).id}">Continuar curso →</button></section>${courseProjectHTML(c.id)}${languageAssessmentsHTML(c)}${[...new Set(c.lessons.map(l=>l.module))].map(m=>`<section class="course-module"><h3>${esc(m)}</h3>${c.lessons.filter(l=>l.module===m).map(l=>`<article class="card"><div class="num">${p.done[l.id]?'✓':c.lessons.indexOf(l)+1}</div><div class="card-body"><h3>${esc(l.title)}</h3><small>Vídeo · teoria · ${l.language?'atividades e escrita':l.drill?'treino cronometrado':'exercício resolvido'}</small></div><button class="study" data-course-lesson="${l.id}">Estudar →</button></article>`).join('')}</section>`).join('')}`:`<div class="scope-tabs course-tabs"><button data-course-kind="all">Todos os cursos</button><button data-course-kind="tech">Informática</button><button data-course-kind="language">Idiomas · 5 cursos</button></div><div class="course-grid">${STUDY_COURSES.filter(c=>courseKind==="all"||(courseKind==="language"?c.kind==="language":c.kind!=="language")).map(c=>{const n=c.lessons.filter(l=>p.done[l.id]).length;return `<article class="course-tile course-${c.id} ${c.kind==='language'?'language-tile':''}">${languageFlagHTML(c)}<span class="eyebrow">CURSO LIVRE · ${c.lessons.length} AULAS</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="track"><i style="width:${n/c.lessons.length*100}%"></i></div><p>${n}/${c.lessons.length} concluídas</p><button class="study" data-course="${c.id}">${n?'Continuar':'Conhecer curso'} →</button></article>`}).join('')}</div>`}`}
function bindCourses(){bindLanguageAssessments();document.querySelectorAll("[data-course-kind]").forEach(b=>{b.classList.toggle("selected",b.dataset.courseKind===courseKind);b.onclick=()=>{courseKind=b.dataset.courseKind;render()}});document.querySelector("#content").insertAdjacentHTML("beforeend",courseCreditsHTML());document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{chosenCourse=b.dataset.course;render()});document.querySelectorAll('[data-course-lesson]').forEach(b=>b.onclick=()=>openCourseLesson(b.dataset.courseLesson));const back=$('#all-courses');if(back)back.onclick=()=>{chosenCourse=null;render()}}
function coursePractice(l){const lab=COURSE_LABS[(l.courseId==='basica'?'basic-':'')+l.source];return `<section class="course-practice"><span class="eyebrow">LABORATÓRIO DO CURSO</span><h3>Da explicação à prática</h3><p>${esc(lab.goal)}</p><h4>Sua missão</h4><p>${esc(lab.task)}</p><details><summary>Conferir resultado esperado e raciocínio</summary><p>${esc(lab.answer)}</p></details><label>Seu resumo e resultado da prática<textarea id="course-notes" placeholder="O que aprendi? Como resolvi? O que preciso repetir?">${esc(courseProgress().notes[l.id]||'')}</textarea></label></section>`}
function openCourseLesson(id){if(courseLessons.find(l=>l.id===id)?.language)return openLanguageLesson(id);const l=courseLessons.find(l=>l.id===id);if(!l)return;stopTyping();active=l;const c=STUDY_COURSES.find(c=>c.id===l.courseId),p=courseProgress(),vid=state.videos[id]||(VIDEO_CATALOG[id]||[])[0]?.id;$('#lesson-content').innerHTML=`<span class="eyebrow">${esc(c.title)} · ${esc(l.module)}</span><h2>${esc(l.title)}</h2><p>Aula ${c.lessons.findIndex(x=>x.id===id)+1} de ${c.lessons.length} · progresso próprio do curso</p>${vid?videoHTML(vid):''}${videoChoicesHTML(l,vid)}${l.drill?`<p class="note">O vídeo apresenta a posição das mãos. A explicação e os exercícios específicos desta etapa estão abaixo.</p><section class="teaching"><h3>Aprenda e pratique</h3><p>${esc(l.theory)}</p>${typingHTML(l)}</section>`:teachingHTML({...l,id:l.source})}${l.drill?`<label>Suas anotações<textarea id="course-notes">${esc(p.notes[id]||'')}</textarea></label>`:coursePractice(l)}<p><button id="course-complete" class="study">${p.done[id]?'Desmarcar conclusão':'Concluir aula ✓'}</button> <button id="course-next">Próxima aula →</button></p>`;$('#course-notes').oninput=e=>{p.notes[id]=e.target.value;save()};$('#course-complete').onclick=()=>{if(p.done[id])delete p.done[id];else p.done[id]=today();save();render();openCourseLesson(id)};const next=c.lessons[c.lessons.findIndex(x=>x.id===id)+1];$('#course-next').disabled=!next;$('#course-next').onclick=()=>openCourseLesson(next.id);if(!$('#lesson').open)$('#lesson').showModal();if(vid)monitorVideo(vid,id);if(l.drill)bindTyping(l)}
function typingHTML(l){const history=courseProgress().typing.filter(x=>x.lessonId===l.id).slice(-5).reverse();return `<div class="keyboard" aria-label="Referência de teclado brasileiro ABNT2">${['Q W E R T Y U I O P','A S D F G H J K L Ç','Z X C V B N M'].map(row=>`<div>${row.split(' ').map(k=>`<kbd class="${'ASDFJKLÇ'.includes(k)?'home-key':''}">${k}</kbd>`).join('')}</div>`).join('')}<small>Referência das letras · F e J orientam os indicadores · polegar no espaço</small></div><p>Use preferencialmente teclado físico. No celular, o teclado virtual também funciona. O texto se repete para permitir treinar durante todo o tempo.</p><label>Duração <select id="typing-duration"><option value="30">30 segundos</option><option value="60" selected>60 segundos</option><option value="120">120 segundos</option></select></label><div class="typing-model" id="typing-model" aria-label="Texto para copiar"></div><label>Digite o modelo aqui<textarea id="typing-input" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" placeholder="O tempo começa na primeira letra."></textarea></label><div id="typing-score" role="status" aria-live="polite">Pronto para começar.</div><p><button id="typing-reset">Reiniciar treino</button> <button id="typing-finish">Encerrar e salvar</button></p><p class="muted">PPM: caracteres corretos na posição final ÷ 5 ÷ minutos. Precisão: inserções corretas ÷ total de caracteres inseridos, incluindo erros depois corrigidos. Colagem não é aceita no treino. Cada tentativa dura no mínimo 5 segundos para ser salva.</p><h4>Últimas tentativas desta aula</h4><div id="typing-history">${history.length?history.map(h=>`<p>${new Date(h.date).toLocaleString('pt-BR')} · ${h.wpm} PPM · ${h.accuracy}% · ${h.elapsed}s</p>`).join(''):'Seus resultados aparecerão aqui.'}</div>`}
function typingMetrics(value,target,attempts,errors,seconds){const correct=Array.from(value).filter((v,i)=>v===Array.from(target)[i]).length;return{wpm:seconds>0?Math.round(correct/5/(seconds/60)):0,accuracy:attempts?Math.round((attempts-errors)/attempts*100):100}}
function stopTyping(){clearInterval(typingTimer);typingTimer=null;typingSession=null}
function bindTyping(l){const input=$('#typing-input'),model=$('#typing-model'),score=$('#typing-score'),duration=$('#typing-duration');let target=Array(200).fill(l.drill).join(' ');function reset(){stopTyping();input.disabled=false;input.value='';duration.disabled=false;typingSession={lessonId:l.id,start:0,limit:Number(duration.value),previous:'',attempts:0,errors:0,finished:false};model.textContent=target.slice(0,350);score.textContent='Pronto para começar.'}function paint(){const s=typingSession;if(!s||s.finished)return;const value=input.value.normalize('NFC'),seconds=s.start?Math.min(s.limit,(Date.now()-s.start)/1000):0,stats=typingMetrics(value,target,s.attempts,s.errors,seconds);score.textContent=`${Math.max(0,Math.ceil(s.limit-seconds))}s restantes · ${stats.wpm} PPM · ${stats.accuracy}% de precisão`;const start=Math.max(0,value.length-60),end=Math.min(target.length,start+350);model.innerHTML=Array.from(target.slice(start,end)).map((ch,i)=>`<span class="${start+i<value.length?(value[start+i]===ch?'typed-good':'typed-bad'):start+i===value.length?'typed-current':''}">${esc(ch)}</span>`).join('');if(s.start&&seconds>=s.limit)finish()}function finish(){const s=typingSession;if(!s||!s.start||s.finished)return;const elapsed=Math.min(s.limit,(Date.now()-s.start)/1000);if(elapsed<5){toast('Treine por pelo menos 5 segundos antes de salvar.');return}s.finished=true;clearInterval(typingTimer);input.disabled=true;const metrics=typingMetrics(input.value.normalize('NFC'),target,s.attempts,s.errors,elapsed),record={lessonId:l.id,...metrics,elapsed:Math.round(elapsed),date:new Date().toISOString()};const p=courseProgress();p.typing.push(record);p.typing=p.typing.slice(-30);save();score.textContent=`Treino salvo: ${metrics.wpm} PPM · ${metrics.accuracy}% · ${record.elapsed}s`;$('#typing-history').insertAdjacentHTML('afterbegin',`<p>Agora · ${metrics.wpm} PPM · ${metrics.accuracy}% · ${record.elapsed}s</p>`)}function changed(e){if(e?.isComposing)return;const s=typingSession;if(!s||s.finished)return;if(s.start&&Date.now()-s.start>=s.limit*1000){input.value=s.previous;finish();return}const value=input.value.normalize('NFC');if(!s.start&&value.length){s.start=Date.now();duration.disabled=true;typingTimer=setInterval(paint,250)}let prefix=0;while(prefix<value.length&&prefix<s.previous.length&&value[prefix]===s.previous[prefix])prefix++;let suffix=0;while(suffix<value.length-prefix&&suffix<s.previous.length-prefix&&value[value.length-1-suffix]===s.previous[s.previous.length-1-suffix])suffix++;for(let i=prefix;i<value.length-suffix;i++){s.attempts++;if(value[i]!==target[i])s.errors++}s.previous=value;paint()}input.oninput=changed;input.oncompositionend=()=>changed();input.onpaste=e=>{e.preventDefault();toast('Digite o texto para medir seu treino.')};input.ondrop=e=>e.preventDefault();$('#typing-reset').onclick=reset;$('#typing-finish').onclick=finish;duration.onchange=reset;reset();$('#lesson').addEventListener('close',stopTyping,{once:true})}
function courseProjectHTML(id){const p=COURSE_PROJECTS[id]||{task:"Projeto de comunicação: apresente uma pessoa, conte um acontecimento e defenda uma ideia no idioma.",steps:["Reúna suas produções de escrita das etapas básica, intermediária e avançada.","Revise o sentido, a estrutura, o vocabulário e o registro usando os roteiros de cada aula. Leia em voz alta e compare com modelos de áudio.","Faça as três provas de etapa e a prova final. Use os comentários para escolher quais aulas precisa repetir."]};return `<details class="course-practice"><summary>Projeto final · colocar em prática</summary><p>${esc(p.task)}</p><ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join("")}</ol><p>Registre seu resultado nas anotações da última aula. Concluir as aulas é uma marcação de estudo pessoal.</p></details>`}
function courseCreditsHTML(){return `<details class="course-practice"><summary>Créditos das imagens dos cursos</summary>${["network","hardware","books"].filter(k=>LEARNING_PHOTOS[k]).map(k=>{const p=LEARNING_PHOTOS[k];return `<p><a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.artist)}</a> · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener">${esc(p.license)}</a>. ${esc(p.changed)}</p>`}).join("")}</details>`}
